/* State dumping routine */
void MOD_mkFPA::dump_state(unsigned int indent)
{
  printf("%*s%s:\n", indent, "", inst_name);
  INST_done_r.dump_state(indent + 2u);
  INST_infinityN1.dump_state(indent + 2u);
  INST_infinityN2.dump_state(indent + 2u);
  INST_n1.dump_state(indent + 2u);
  INST_n2.dump_state(indent + 2u);
  INST_nanN1.dump_state(indent + 2u);
  INST_nanN2.dump_state(indent + 2u);
  INST_normalizeShiftCount.dump_state(indent + 2u);
  INST_result.dump_state(indent + 2u);
  INST_resultMantissa.dump_state(indent + 2u);
  INST_stage.dump_state(indent + 2u);
}


/* VCD dumping routines */

unsigned int MOD_mkFPA::dump_VCD_defs(unsigned int levels)
{
  vcd_write_scope_start(sim_hdl, inst_name);
  vcd_num = vcd_reserve_ids(sim_hdl, 25u);
  unsigned int num = vcd_num;
  for (unsigned int clk = 0u; clk < bk_num_clocks(sim_hdl); ++clk)
    vcd_add_clock_def(sim_hdl, this, bk_clock_name(sim_hdl, clk), bk_clock_vcd_num(sim_hdl, clk));
  vcd_write_def(sim_hdl, bk_clock_vcd_num(sim_hdl, __clk_handle_0), "CLK", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "NOT_n1_BITS_30_TO_23_EQ_0_6___d47", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50", 1u);
  vcd_write_def(sim_hdl, num++, "RST_N", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "_read__h379", 8u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "n1__h1546", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "n2__h1572", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "resultMantissa__h1646", 25u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "stage__h433", 3u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h1525", 8u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h1551", 8u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h589", 23u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h748", 23u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h843", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "y__h844", 1u);
  num = INST_done_r.dump_VCD_defs(num);
  num = INST_infinityN1.dump_VCD_defs(num);
  num = INST_infinityN2.dump_VCD_defs(num);
  num = INST_n1.dump_VCD_defs(num);
  num = INST_n2.dump_VCD_defs(num);
  num = INST_nanN1.dump_VCD_defs(num);
  num = INST_nanN2.dump_VCD_defs(num);
  num = INST_normalizeShiftCount.dump_VCD_defs(num);
  num = INST_result.dump_VCD_defs(num);
  num = INST_resultMantissa.dump_VCD_defs(num);
  num = INST_stage.dump_VCD_defs(num);
  vcd_write_scope_end(sim_hdl);
  return num;
}

void MOD_mkFPA::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_mkFPA &backing)
{
  vcd_defs(dt, backing);
  vcd_prims(dt, backing);
}

void MOD_mkFPA::vcd_defs(tVCDDumpType dt, MOD_mkFPA &backing)
{
  unsigned int num = vcd_num;
  if (dt == VCD_DUMP_XS)
  {
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 8u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 25u);
    vcd_write_x(sim_hdl, num++, 3u);
    vcd_write_x(sim_hdl, num++, 8u);
    vcd_write_x(sim_hdl, num++, 8u);
    vcd_write_x(sim_hdl, num++, 23u);
    vcd_write_x(sim_hdl, num++, 23u);
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 1u);
  }
  else
    if (dt == VCD_DUMP_CHANGES)
    {
      if ((backing.DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47) != DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47)
      {
	vcd_write_val(sim_hdl, num, DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47, 1u);
	backing.DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47 = DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47;
      }
      ++num;
      if ((backing.DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50) != DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50)
      {
	vcd_write_val(sim_hdl, num, DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50, 1u);
	backing.DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50 = DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50;
      }
      ++num;
      if ((backing.PORT_RST_N) != PORT_RST_N)
      {
	vcd_write_val(sim_hdl, num, PORT_RST_N, 1u);
	backing.PORT_RST_N = PORT_RST_N;
      }
      ++num;
      if ((backing.DEF__read__h379) != DEF__read__h379)
      {
	vcd_write_val(sim_hdl, num, DEF__read__h379, 8u);
	backing.DEF__read__h379 = DEF__read__h379;
      }
      ++num;
      if ((backing.DEF_n1__h1546) != DEF_n1__h1546)
      {
	vcd_write_val(sim_hdl, num, DEF_n1__h1546, 32u);
	backing.DEF_n1__h1546 = DEF_n1__h1546;
      }
      ++num;
      if ((backing.DEF_n2__h1572) != DEF_n2__h1572)
      {
	vcd_write_val(sim_hdl, num, DEF_n2__h1572, 32u);
	backing.DEF_n2__h1572 = DEF_n2__h1572;
      }
      ++num;
      if ((backing.DEF_resultMantissa__h1646) != DEF_resultMantissa__h1646)
      {
	vcd_write_val(sim_hdl, num, DEF_resultMantissa__h1646, 25u);
	backing.DEF_resultMantissa__h1646 = DEF_resultMantissa__h1646;
      }
      ++num;
      if ((backing.DEF_stage__h433) != DEF_stage__h433)
      {
	vcd_write_val(sim_hdl, num, DEF_stage__h433, 3u);
	backing.DEF_stage__h433 = DEF_stage__h433;
      }
      ++num;
      if ((backing.DEF_x__h1525) != DEF_x__h1525)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h1525, 8u);
	backing.DEF_x__h1525 = DEF_x__h1525;
      }
      ++num;
      if ((backing.DEF_x__h1551) != DEF_x__h1551)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h1551, 8u);
	backing.DEF_x__h1551 = DEF_x__h1551;
      }
      ++num;
      if ((backing.DEF_x__h589) != DEF_x__h589)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h589, 23u);
	backing.DEF_x__h589 = DEF_x__h589;
      }
      ++num;
      if ((backing.DEF_x__h748) != DEF_x__h748)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h748, 23u);
	backing.DEF_x__h748 = DEF_x__h748;
      }
      ++num;
      if ((backing.DEF_x__h843) != DEF_x__h843)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h843, 1u);
	backing.DEF_x__h843 = DEF_x__h843;
      }
      ++num;
      if ((backing.DEF_y__h844) != DEF_y__h844)
      {
	vcd_write_val(sim_hdl, num, DEF_y__h844, 1u);
	backing.DEF_y__h844 = DEF_y__h844;
      }
      ++num;
    }
    else
    {
      vcd_write_val(sim_hdl, num++, DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47, 1u);
      backing.DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47 = DEF_NOT_n1_BITS_30_TO_23_EQ_0_6___d47;
      vcd_write_val(sim_hdl, num++, DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50, 1u);
      backing.DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50 = DEF_NOT_n2_3_BITS_30_TO_23_4_EQ_0_9___d50;
      vcd_write_val(sim_hdl, num++, PORT_RST_N, 1u);
      backing.PORT_RST_N = PORT_RST_N;
      vcd_write_val(sim_hdl, num++, DEF__read__h379, 8u);
      backing.DEF__read__h379 = DEF__read__h379;
      vcd_write_val(sim_hdl, num++, DEF_n1__h1546, 32u);
      backing.DEF_n1__h1546 = DEF_n1__h1546;
      vcd_write_val(sim_hdl, num++, DEF_n2__h1572, 32u);
      backing.DEF_n2__h1572 = DEF_n2__h1572;
      vcd_write_val(sim_hdl, num++, DEF_resultMantissa__h1646, 25u);
      backing.DEF_resultMantissa__h1646 = DEF_resultMantissa__h1646;
      vcd_write_val(sim_hdl, num++, DEF_stage__h433, 3u);
      backing.DEF_stage__h433 = DEF_stage__h433;
      vcd_write_val(sim_hdl, num++, DEF_x__h1525, 8u);
      backing.DEF_x__h1525 = DEF_x__h1525;
      vcd_write_val(sim_hdl, num++, DEF_x__h1551, 8u);
      backing.DEF_x__h1551 = DEF_x__h1551;
      vcd_write_val(sim_hdl, num++, DEF_x__h589, 23u);
      backing.DEF_x__h589 = DEF_x__h589;
      vcd_write_val(sim_hdl, num++, DEF_x__h748, 23u);
      backing.DEF_x__h748 = DEF_x__h748;
      vcd_write_val(sim_hdl, num++, DEF_x__h843, 1u);
      backing.DEF_x__h843 = DEF_x__h843;
      vcd_write_val(sim_hdl, num++, DEF_y__h844, 1u);
      backing.DEF_y__h844 = DEF_y__h844;
    }
}

void MOD_mkFPA::vcd_prims(tVCDDumpType dt, MOD_mkFPA &backing)
{
  INST_done_r.dump_VCD(dt, backing.INST_done_r);
  INST_infinityN1.dump_VCD(dt, backing.INST_infinityN1);
  INST_infinityN2.dump_VCD(dt, backing.INST_infinityN2);
  INST_n1.dump_VCD(dt, backing.INST_n1);
  INST_n2.dump_VCD(dt, backing.INST_n2);
  INST_nanN1.dump_VCD(dt, backing.INST_nanN1);
  INST_nanN2.dump_VCD(dt, backing.INST_nanN2);
  INST_normalizeShiftCount.dump_VCD(dt, backing.INST_normalizeShiftCount);
  INST_result.dump_VCD(dt, backing.INST_result);
  INST_resultMantissa.dump_VCD(dt, backing.INST_resultMantissa);
  INST_stage.dump_VCD(dt, backing.INST_stage);
}
